def inspect_clue(clue):
    if clue == "gray dust":
        return f"FLAG: {clue}"
    else:
        return f"logged: {clue}"

evidence = [
    "broken lantern",
    "gray dust",
    "torn cloak",
]

def inspect_clue(clue):
    if clue == "gray dust":
        return f"FLAG: {clue}"
    else:
        return f"logged: {clue}"

for clue in evidence:
    print(inspect_clue(clue))
